function relFor(q){q=String(q||"").trim();if(!q)return null;const rl=RLX().releases,u=q.toUpperCase();let r=rl.find(x=>x.id===u);if(r)return r;const c=chgOf(u);if(c&&c.rel){r=rl.find(x=>x.id===c.rel);if(r)return r}r=rl.find(x=>(x.chg||[]).includes(u)||(x.feats||[]).includes(u));if(r)return r;const run=RUNS().find(x=>x.id===u||x.sha===q.toLowerCase()||String(x.prn)===q.replace("#",""));if(run&&run.rel)return rl.find(x=>x.id===run.rel)||null;return rl.find(x=>x.n.toLowerCase().includes(q.toLowerCase()))||null}
