/* ---------- freezes and clashes ---------- */
function calSvg(){const start=dn(TODAY),span=120,W=980,Hh=150,L=10,x=d=>L+(dn(d)-start)/span*(W-L-10);let g="";
 for(let m=0;m<5;m++){const d=new Date(Date.UTC(2026,9+m,1)),s=dfrom(Math.floor(d.getTime()/864e5));if(dn(s)<start-1)continue;g+=`<line x1="${x(s)}" x2="${x(s)}" y1="22" y2="${Hh-24}" class="gl"/><text x="${x(s)+4}" y="16" class="tx">${MON[d.getUTCMonth()]} ${d.getUTCFullYear()}</text>`}
 FRZ().forEach(f=>{if(dn(f.to)<start||dn(f.from)>start+span)return;const a=x(f.from<TODAY?TODAY:f.from),b=x(f.to>addD(TODAY,span)?addD(TODAY,span):f.to);g+=`<rect x="${a}" y="26" width="${Math.max(3,b-a)}" height="${Hh-60}" rx="6" style="fill:var(${f.kind==="Blackout"?"--bad-f":"--warn-f"});opacity:.16"><title>${H(f.n+" ("+f.kind+"): "+fd(f.from)+" to "+fd(f.to))}</title></rect><text x="${a+4}" y="42" class="tx" style="fill:var(${f.kind==="Blackout"?"--bad-f":"--muted"})">${H(f.n)}</text>`});
 const rels=RLX().releases.filter(r=>r.st!=="Deployed"&&r.st!=="Rolled back"&&r.date>=TODAY&&dn(r.date)<=start+span);rels.forEach((r,i)=>{const hard=RLX().clashes(r.id).some(c=>c.k==="hard"),y=62+(i%4)*17;g+=`<circle cx="${x(r.date)}" cy="${y}" r="5" style="fill:var(${hard?"--bad-f":"--p4"})" data-dev-rel="${r.id}" tabindex="0" role="button" aria-label="${H(r.id+" "+r.n+" on "+fd(r.date))}"><title>${H(r.id+" "+r.n+", "+fd(r.date)+(hard?", hard clash":""))}</title></circle>`});
 g+=`<line x1="${x(TODAY)}" x2="${x(TODAY)}" y1="20" y2="${Hh-24}" class="tg"/><text x="${x(TODAY)+4}" y="${Hh-10}" class="tx">Today</text>`;return `<div class="dev-ch"><svg viewBox="0 0 ${W} ${Hh}" role="img" aria-label="Deployment calendar for the next 120 days with freezes and planned releases">${g}</svg></div>`}
function canDeploy(date,svc){const f=frzOn(date),clash=RLX().releases.filter(r=>r.st!=="Deployed"&&r.st!=="Rolled back"&&r.date===date&&(!svc||r.svc===svc));return f?{ok:false,t:fd(date)+" is inside the "+f.n+" ("+f.kind.toLowerCase()+", "+fd(f.from)+" to "+fd(f.to)+"). Standard changes are not auto\u2011approved. A hotfix needs a CIO exception."}:{ok:true,t:fd(date)+" has no freeze."+(clash.length?" "+clash.length+" other release"+(clash.length>1?"s are":" is")+" planned that day: "+clash.map(c=>c.id).join(", ")+".":" No other release is planned that day.")}}
